gelu_cpp_source = """
#include <hip/hip_runtime.h>
#include <math.h>

#define BLOCK_SIZE 256

__global__ void gelu_kernel(const float* x, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < size) {
        float x_val = x[idx];
        // GELU approximation: 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
        const float sqrt_2_over_pi = 0.7978845608028654f;
        const float coef = 0.044715f;
        float x_cubed = x_val * x_val * x_val;
        float tanh_in = sqrt_2_over_pi * (x_val + coef * x_cubed);
        float tanh_val = tanhf(tanh_in);
        out[idx] = 0.5f * x_val * (1.0f + tanh_val);
    }
}

torch::Tensor gelu_hip(torch::Tensor x) {
    int size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = BLOCK_SIZE;
    const int num_blocks = (size + block_size - 1) / block_size;

    dim3 grid(num_blocks);
    dim3 block(block_size);

    hipLaunchKernelGGL(gelu_kernel, grid, block, 0, 0, 
                       x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

gelu_module = load_inline(
    name="gelu_module",
    cpp_sources=gelu_cpp_source,
    functions=["gelu_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    """
    Optimized model that performs GELU activation using custom HIP kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.gelu_hip = gelu_module.gelu_hip

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies GELU activation to the input tensor using optimized HIP kernel.

        Args:
            x (torch.Tensor): Input tensor of any shape.

        Returns:
            torch.Tensor: Output tensor with GELU applied, same shape as input.
        """
        return self.gelu_hip(x)

# Helper function to create model instance
def create_model():
    return ModelNew()

