matmul_source = """
#include <hip/hip_runtime.h>

#define BLOCK_SIZE 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global position in C
    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    // Accumulator
    float sum = 0.0f;

    // Loop over tiles of K
    int num_tiles = (K + BLOCK_SIZE - 1) / BLOCK_SIZE;
    for (int tile = 0; tile < num_tiles; ++tile) {
        // Shared memory for tiles
        __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
        __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

        // Load A tile (coalesced read from A)
        int a_row = row;
        int a_col = tile * BLOCK_SIZE + tx;
        As[ty][tx] = (a_row < M && a_col < K) ? A[a_row * K + a_col] : 0.0f;

        // Load B tile (coalesced read from B)
        int b_row = tile * BLOCK_SIZE + ty;
        int b_col = col;
        Bs[ty][tx] = (b_row < K && b_col < N) ? B[b_row * N + b_col] : 0.0f;

        __syncthreads();

        // Compute partial result for this tile
        for (int k = 0; k < BLOCK_SIZE && (tile * BLOCK_SIZE + k) < K; ++k) {
            sum += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    // Write result (coalesced write to C)
    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    auto M = A.size(0);
    auto K = A.size(1);
    auto N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 block(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (M + BLOCK_SIZE - 1) / BLOCK_SIZE);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        M, K, N
    );

    return C;
}
"""

matmul_lib = load_inline(
    name="matmul_lib",
    cpp_sources=matmul_source,
    functions=["matmul_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) with irregular shapes
    using a tiled HIP kernel with shared memory for better performance.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_hip = matmul_lib

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix multiplication of A and B using optimized HIP kernel.

        Args:
            A: Input tensor with shape (M, K).
            B: Input tensor with shape (K, N).

        Returns:
            C: Output tensor with shape (M, N).
        """
        return self.matmul_hip.matmul_hip(A.cuda(), B.cuda())

