conv2d_hip_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_WIDTH 32
#define TILE_HEIGHT 32

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int in_height,
    const int in_width,
    const int out_height,
    const int out_width,
    const int kernel_height,
    const int kernel_width,
    const int stride_h,
    const int stride_w,
    const int pad_h,
    const int pad_w,
    const int dilation_h,
    const int dilation_w,
    const int groups) {

    // Output position
    const int out_x = blockIdx.x * blockDim.x + threadIdx.x;
    const int out_y = blockIdx.y * blockDim.y + threadIdx.y;
    const int out_c = blockIdx.z;

    if (out_x >= out_width || out_y >= out_height || out_c >= out_channels) return;

    // Calculate input region
    const int in_y_start = out_y * stride_h - pad_h;
    const int in_x_start = out_x * stride_w - pad_w;

    float sum = 0.0f;

    // Loop over input channels and kernel
    for (int in_c = 0; in_c < in_channels; ++in_c) {
        #pragma unroll
        for (int ky = 0; ky < kernel_height; ++ky) {
            const int in_y = in_y_start + ky * dilation_h;
            if (in_y < 0 || in_y >= in_height) continue;

            #pragma unroll
            for (int kx = 0; kx < kernel_width; ++kx) {
                const int in_x = in_x_start + kx * dilation_w;
                if (in_x < 0 || in_x >= in_width) continue;

                // Compute indices
                const int input_idx = 
                    (blockIdx.w * in_channels + in_c) * in_height * in_width +
                    in_y * in_width + in_x;
                const int weight_idx = 
                    out_c * in_channels * kernel_height * kernel_width +
                    in_c * kernel_height * kernel_width +
                    ky * kernel_width + kx;

                sum += input[input_idx] * weight[weight_idx];
            }
        }
    }

    // Add bias if available
    if (bias != nullptr) {
        sum += bias[out_c];
    }

    // Write output for all batches
    for (int b = 0; b < batch_size; ++b) {
        const int output_idx = 
            (b * out_channels + out_c) * out_height * out_width +
            out_y * out_width + out_x;
        output[output_idx] = sum;
    }
}

torch::Tensor conv2d_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h,
    int stride_w,
    int padding_h,
    int padding_w,
    int dilation_h,
    int dilation_w,
    int groups) {

    const auto batch_size = input.size(0);
    const auto in_channels = input.size(1);
    const auto in_height = input.size(2);
    const auto in_width = input.size(3);
    const auto out_channels = weight.size(0);
    const auto kernel_height = weight.size(2);
    const auto kernel_width = weight.size(3);

    const auto out_height = (in_height + 2 * padding_h - dilation_h * (kernel_height - 1) - 1) / stride_h + 1;
    const auto out_width = (in_width + 2 * padding_w - dilation_w * (kernel_width - 1) - 1) / stride_w + 1;

    auto output = torch::zeros({batch_size, out_channels, out_height, out_width}, input.options());

    const int threads_per_block = 256;
    dim3 blockDim(16, 16, 1);
    dim3 gridDim(
        (out_width + blockDim.x - 1) / blockDim.x,
        (out_height + blockDim.y - 1) / blockDim.y,
        out_channels,
        batch_size);

    const float* bias_ptr = bias.numel() > 0 ? bias.data_ptr<float>() : nullptr;

    hipLaunchKernelGGL(conv2d_kernel,
        gridDim, blockDim, 0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_height,
        in_width,
        out_height,
        out_width,
        kernel_height,
        kernel_width,
        stride_h,
        stride_w,
        padding_h,
        padding_w,
        dilation_h,
        dilation_w,
        groups);

    return output;
}
"""

conv2d_hip = load_inline(
    name="conv2d_hip",
    cpp_sources=conv2d_hip_source,
    functions=["conv2d_hip"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Performs a 2D convolution using a custom optimized HIP kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, 
                 stride: int = 1, padding: int = 0, dilation: int = 1, 
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self Bias = bias

        self.conv2d_hip_impl = conv2d_hip

        # Initialize weight and bias
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        # Initialize parameters
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the 2D convolution using custom HIP kernel.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, height_out, width_out).
        """
        bias_tensor = self.bias if self.bias is not None else torch.empty(0, device=x.device)

        return self.conv2d_hip_impl.conv2d_hip(
            x,
            self.weight,
            bias_tensor,
            self.stride,
            self.stride,
            self.padding,
            self.padding,
            self.dilation,
            self.dilation,
            self.groups
        )

