layernorm_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define EPSILON 1e-5f
#define MAX_BLOCK_SIZE 1024

// Warp shuffle function for reducing within a warp
__device__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

// LayerNorm kernel optimized for 4D tensors
__global__ void layernorm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int batch_size,
    int features,
    int dim1,
    int dim2,
    int normalized_size)
{
    int batch_idx = blockIdx.y;
    int feat_idx = blockIdx.x;

    if (batch_idx >= batch_size || feat_idx >= features) return;

    // Each thread processes multiple elements along dim1, dim2
    int elements_per_thread = (dim1 * dim2 + blockDim.x - 1) / blockDim.x;
    int start_elem = threadIdx.x * elements_per_thread;
    int end_elem = min(start_elem + elements_per_thread, dim1 * dim2);

    // Base offset for this batch and feature
    int batch_offset = batch_idx * features * dim1 * dim2;
    int base_offset = batch_offset + feat_idx * dim1 * dim2;

    // Compute mean
    float sum = 0.0f;
    int count = 0;

    for (int elem = start_elem; elem < end_elem; elem++) {
        int offset = base_offset + elem;
        sum += input[offset];
        count++;
    }

    // Block-level reduction for sum
    __shared__ float shared_sums[MAX_BLOCK_SIZE];
    shared_sums[threadIdx.x] = sum;
    __syncthreads();

    // Reduce within block using warp shuffle
    int warp_idx = threadIdx.x / 32;
    int lane_idx = threadIdx.x % 32;

    float warp_sum = warp_reduce_sum(shared_sums[32 * warp_idx + lane_idx]);

    if (lane_idx == 0) {
        shared_sums[warp_idx] = warp_sum;
    }
    __syncthreads();

    // Final reduction of warp sums
    float final_sum = 0.0f;
    if (warp_idx == 0 && lane_idx < (blockDim.x + 31) / 32) {
        final_sum = shared_sums[lane_idx];
    }

    float total_sum = warp_reduce_sum(final_sum);
    float mean = total_sum / normalized_size;

    // Broadcast mean to all threads
    __shared__ float shared_mean;
    if (threadIdx.x == 0) {
        shared_mean = mean;
    }
    __syncthreads();

    // Compute variance (sum of squared differences)
    float sq_diff_sum = 0.0f;

    for (int elem = start_elem; elem < end_elem; elem++) {
        int offset = base_offset + elem;
        float diff = input[offset] - shared_mean;
        sq_diff_sum += diff * diff;
    }

    // Block-level reduction for sq_diff_sum
    shared_sums[threadIdx.x] = sq_diff_sum;
    __syncthreads();

    warp_sum = warp_reduce_sum(shared_sums[32 * warp_idx + lane_idx]);

    if (lane_idx == 0) {
        shared_sums[warp_idx] = warp_sum;
    }
    __syncthreads();

    final_sum = 0.0f;
    if (warp_idx == 0 && lane_idx < (blockDim.x + 31) / 32) {
        final_sum = shared_sums[lane_idx];
    }

    float total_sq_diff = warp_reduce_sum(final_sum);
    float variance = total_sq_diff / normalized_size;
    float inv_std = rsqrtf(variance + EPSILON);

    // Broadcast inv_std to all threads
    __shared__ float shared_inv_std;
    if (threadIdx.x == 0) {
        shared_inv_std = inv_std;
    }
    __syncthreads();

    // Apply normalization with gamma and beta
    float g = gamma[feat_idx];
    float b = beta[feat_idx];

    for (int elem = start_elem; elem < end_elem; elem++) {
        int offset = base_offset + elem;
        output[offset] = g * (input[offset] - shared_mean) * shared_inv_std + b;
    }
}

