rms_norm_cpp_source = """
#include <hip/hip_runtime.h>

constexpr int WARP_SIZE = 64;

__device__ float warp_reduce_sum(float sum) {
    #pragma unroll
    for (int offset = 32; offset > 0; offset /= 2) {
        sum += __shfl_down(sum, offset);
    }
    return sum;
}

__global__ void rms_norm_kernel(const float* __restrict__ x, 
                                float* __restrict__ out, 
                                int batch_size,
                                int features,
                                int dim1,
                                int dim2,
                                float eps) {
    // Each block handles one spatial position (batch_idx, d1_idx, d2_idx)
    int batch_idx = blockIdx.z;
    int d1_idx = blockIdx.y;
    int d2_idx = blockIdx.x;

    // Each thread processes some elements from the features dimension
    int features_per_thread = (features + blockDim.x - 1) / blockDim.x;
    int start_feature = threadIdx.x * features_per_thread;
    int end_feature = min(start_feature + features_per_thread, features);

    // Compute sum of squares for this spatial position
    float sum_sq = 0.0f;

    // Base pointer for this spatial position
    const float* x_ptr = x + (batch_idx * dim1 * dim2 + d1_idx * dim2 + d2_idx) * features;

    for (int f = start_feature; f < end_feature; f++) {
        float val = x_ptr[f];
        sum_sq += val * val;
    }

    // Reduce sum_sq across threads using warp reduction
    float warp_sum = warp_reduce_sum(sum_sq);

    // First thread of each warp stores partial sum to shared memory
    __shared__ float shared_sums[WARP_SIZE];
    int lane_id = threadIdx.x % WARP_SIZE;
    int warp_id = threadIdx.x / WARP_SIZE;

    if (lane_id == 0) {
        shared_sums[warp_id] = warp_sum;
    }
    __syncthreads();

    // Reduce across warps
    float total_sum = 0.0f;
    int num_warps = (blockDim.x + WARP_SIZE - 1) / WARP_SIZE;
    if (threadIdx.x < num_warps) {
        total_sum = shared_sums[threadIdx.x];
    }

    // Final reduction of partial sums
    if (threadIdx.x == 0) {
        #pragma unroll
        for (int i = 1; i < num_warps; i++) {
            total_sum += shared_sums[i];
        }
        // Compute RMS
        float mean_sq = total_sum / features;
        float rms = sqrtf(mean_sq + eps);
        shared_sums[0] = rms;
    }
    __syncthreads();

    float rms_val = shared_sums[0];
    float* out_ptr = out + (batch_idx * dim1 * dim2 + d1_idx * dim2 + d2_idx) * features;

    // Divide by RMS and write output
    for (int f = start_feature; f < end_feature; f++) {
        out_ptr[f] = x_ptr[f] / rms_val;
    }
}

