softmax_cpp_source = """
#include <hip/hip_runtime.h>

#define warpSize 64

__device__ float warp_reduce_max(float val) {
    for (int offset = warpSize / 2; offset > 0; offset /= 2) {
        float other = __shfl_down(val, offset);
        if (other > val) val = other;
    }
    return val;
}

__device__ float warp_reduce_sum(float val) {
    for (int offset = warpSize / 2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

template<int BLOCK_SIZE>
__global__ void softmax_kernel(const float* __restrict__ x, float* __restrict__ out, int batch_size, int dim) {
    extern __shared__ float sdata[];

    int row = blockIdx.x;
    int tid = threadIdx.x;

    if (row >= batch_size) return;

    const float* row_ptr = x + row * dim;

    // First pass: find max value
    float max_val = -1e20f;
    for (int i = tid; i < dim; i += BLOCK_SIZE) {
        float val = row_ptr[i];
        if (val > max_val) max_val = val;
    }

    max_val = warp_reduce_max(max_val);

    // Block-level reduce for max
    if (tid % warpSize == 0) {
        sdata[tid / warpSize] = max_val;
    }
    __syncthreads();

    if (tid < (BLOCK_SIZE / warpSize)) {
        max_val = sdata[tid];
        max_val = warp_reduce_max(max_val);
        if (tid == 0) sdata[0] = max_val;
    }
    __syncthreads();
    max_val = sdata[0];

    // Second pass: compute sum of exp
    float sum_val = 0.0f;
    for (int i = tid; i < dim; i += BLOCK_SIZE) {
        sum_val += expf(row_ptr[i] - max_val);
    }

    sum_val = warp_reduce_sum(sum_val);

    // Block-level reduce for sum
    if (tid % warpSize == 0) {
        sdata[tid / warpSize] = sum_val;
    }
    __syncthreads();

    if (tid < (BLOCK_SIZE / warpSize)) {
        sum_val = sdata[tid];
        sum_val = warp_reduce_sum(sum_val);
        if (tid == 0) sdata[0] = sum_val;
    }
    __syncthreads();
    sum_val = sdata[0];

    // Third pass: compute softmax
    float* out_ptr = out + row * dim;
    for (int i = tid; i < dim; i += BLOCK_SIZE) {
        out_ptr[i] = expf(row_ptr[i] - max_val) / sum_val;
    }
}

torch::Tensor softmax_hip(torch::Tensor x) {
    auto batch_size = x.size(0);
    auto dim = x.size(1);

    auto out = torch::zeros_like(x);

    const int BLOCK_SIZE = 256;
    dim3 block(BLOCK_SIZE);
    dim3 grid(batch_size);

    int smem_size = (BLOCK_SIZE / 64) * sizeof(float) * 2;

    hipLaunchKernelGGL(HIP_KERNEL_NAME(softmax_kernel<BLOCK_SIZE>), 
                       grid, block, smem_size, 0,
                       x.data_ptr<float>(), out.data_ptr<float>(), 
                       batch_size, dim);

    return out;
}
