depthwise_conv2d_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int height,
    const int width,
    const int kernel_size,
    const int stride,
    const int padding,
    const int height_out,
    const int width_out
) {
    const int TILE_H = 16;
    const int TILE_W = 16;

    // Shared memory for input tile (with padding for kernel access)
    __shared__ float shared_input[TILE_H + 2][TILE_W + 2];

    // Compute output position
    const int out_h = blockIdx.y * blockDim.y + threadIdx.y;
    const int out_w = blockIdx.x * blockDim.x + threadIdx.x;

    // Channel and batch
    const int c = blockIdx.z;
    const int b = blockIdx.z / in_channels;
    const int ch = blockIdx.z % in_channels;

    // Weight offset for this channel (depthwise: 1 weight per channel)
    const float* weight_ptr = weight + ch * kernel_size * kernel_size;

    // Load shared memory (each thread loads one element)
    const int half_k = 1; // assuming kernel_size=3

    int load_h = out_h - padding + half_k;
    int load_w = out_w - padding + half_k;

    // Check bounds
    if (load_h < TILE_H + 2 && load_w < TILE_W + 2) {
        int in_h = load_h - half_k + padding;
        int in_w = load_w - half_k + padding;

        if (in_h >= 0 && in_h < height && in_w >= 0 && in_w < width) {
            int input_offset = b * in_channels * height * width + ch * height * width + in_h * width + in_w;
            shared_input[load_h][load_w] = input[input_offset];
        } else {
            shared_input[load_h][load_w] = 0.0f;
        }
    }

    __syncthreads();

    // Compute output if within bounds
    if (out_h < height_out && out_w < width_out) {
        float sum = 0.0f;

        for (int kh = 0; kh < kernel_size; kh++) {
            for (int kw = 0; kw < kernel_size; kw++) {
                int in_h_load = threadIdx.y + kh;
                int in_w_load = threadIdx.x + kw;

                if (in_h_load < TILE_H + 2 && in_w_load < TILE_W + 2) {
                    float in_val = shared_input[in_h_load][in_w_load];
                    float w_val = weight_ptr[kh * kernel_size + kw];
                    sum += in_val * w_val;
                }
            }
        }

        int output_offset = b * in_channels * height_out * width_out + ch * height_out * width_out + out_h * width_out + out_w;
        output[output_offset] = sum;
    }
}

torch::Tensor depthwise_conv2d_hip(torch::Tensor input, torch::Tensor weight, int kernel_size, int stride, int padding) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto height_out = (height + 2 * padding - kernel_size) / stride + 1;
    auto width_out = (width + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({batch_size, in_channels, height_out, width_out}, input.options());

    const int TILE_H = 16;
    const int TILE_W = 16;

    dim3 block(TILE_W, TILE_H);
    dim3 grid((width_out + TILE_W - 1) / TILE_W, (height_out + TILE_H - 1) / TILE_H, batch_size * in_channels);

    depthwise_conv2d_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        height,
        width,
        kernel_size,
        stride,
        padding,
        height_out,
        width_out
    );

    return output;
}
"""

depthwise_conv2d = load_inline(
