    // Use shared memory for tiles
    __shared__ float As[TILE_SIZE];
    __shared__ float Bs[TILE_SIZE];

    // Each block computes multiple output rows (ROWS_PER_BLOCK)
    const int ROWS_PER_BLOCK = blockDim.x;

    int row_start = blockIdx.x * ROWS_PER_BLOCK + threadIdx.x;

    // Thread-local accumulator
    float sum = 0.0f;

    // Iterate over tiles
    for (int tile_idx = 0; tile_idx < K; tile_idx += TILE_SIZE) {
        // Each thread loads one element of A and B into shared memory
        // Load B (vector) - same for all threads in block
        if (threadIdx.x < TILE_SIZE && tile_idx + threadIdx.x < K) {
            Bs[threadIdx.x] = B[tile_idx + threadIdx.x];
        }

        // Load A (matrix) - each thread loads from its row
        if (row_start < M && threadIdx.x < TILE_SIZE && tile_idx + threadIdx.x < K) {
            As[threadIdx.x] = A[row_start * K + tile_idx + threadIdx.x];
        }

        __syncthreads();

        // Compute partial dot product
        if (row_start < M) {
            float thread_sum = 0.0f;
            for (int j = 0; j < TILE_SIZE; j++) {
                int k_idx = tile_idx + j;
                if (k_idx < K) {
                    thread_sum += As[j] * Bs[j];
                }
            }
            sum += thread_sum;
        }

        __syncthreads();
    }

    // Write result
    if (row_start < M) {
        C[row_start] = sum;
    }
}

