maxpool2d_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void maxpool2d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int batch_size,
    const int channels,
    const int height,
    const int width,
    const int out_height,
    const int out_width,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int out_w = out_width;
    const int total_out_spatial = out_height * out_width;

    const int channel = (idx / total_out_spatial) % channels;
    const int idx_in_spatial = idx % total_out_spatial;
    const int out_y = idx_in_spatial / out_w;
    const int out_x = idx_in_spatial % out_w;
    const int batch = idx / (total_out_spatial * channels);

    if (out_x >= out_width || out_y >= out_height || channel >= channels || batch >= batch_size) {
        return;
    }

    float max_val = -1e20f;

    for (int ky = 0; ky < kernel_size; ++ky) {
        for (int kx = 0; kx < kernel_size; ++kx) {
            int input_y = out_y * stride + ky * dilation - padding;
            int input_x = out_x * stride + kx * dilation - padding;

            if (input_y >= 0 && input_y < height && input_x >= 0 && input_x < width) {
                int input_idx = ((batch * channels + channel) * height + input_y) * width + input_x;
                max_val = fmaxf(max_val, input[input_idx]);
            }
        }
    }

    int output_idx = ((batch * channels + channel) * out_height + out_y) * out_width + out_x;
    output[output_idx] = max_val;
}

torch::Tensor maxpool2d_hip(
    torch::Tensor input,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation
) {
    const int batch_size = input.size(0);
    const int channels = input.size(1);
    const int height = input.size(2);
    const int width = input.size(3);

    const int out_height = (height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    const int out_width = (width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, channels, out_height, out_width}, input.options());

    const int block_size = 256;
    const int num_blocks = (batch_size * channels * out_height * out_width + block_size - 1) / block_size;

    maxpool2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width,
        out_height,
        out_width,
        kernel_size,
        stride,
        padding,
        dilation
    );

    return output;
}
"""

