gelu_cpp_source = """
#include <hip/hip_runtime.h>

#define BLOCK_SIZE 512
#define VEC_SIZE 4

__global__ void gelu_kernel(const float* x, float* out, int size) {
    int idx = (blockIdx.x * blockDim.x + threadIdx.x) * VEC_SIZE;

    if (idx < size) {
        // Process 4 elements per thread for better memory utilization
        float4 x_vec = reinterpret_cast<const float4&>(x[idx]);

        // GELU approximation: 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
        const float sqrt_2_over_pi = 0.7978845608028654f;
        const float coef = 0.044715f;
        const float half = 0.5f;
        const float one = 1.0f;

        // Compute GELU for each component
        #pragma unroll
        for (int i = 0; i < VEC_SIZE && (idx + i) < size; i++) {
            float x_val = (i == 0) ? x_vec.x : (i == 1) ? x_vec.y : (i == 2) ? x_vec.z : x_vec.w;
            float x_cubed = x_val * x_val * x_val;
            float tanh_in = sqrt_2_over_pi * (x_val + coef * x_cubed);
            float tanh_val = tanhf(tanh_in);
            float result = half * x_val * (one + tanh_val);

            // Store result
            if (i == 0) x_vec.x = result;
            else if (i == 1) x_vec.y = result;
            else if (i == 2) x_vec.z = result;
            else x_vec.w = result;
        }

        reinterpret_cast<float4&>(out[idx]) = x_vec;
    }
}

torch::Tensor gelu_hip(torch::Tensor x) {
    int size = x.numel();
    auto out = torch::zeros_like(x);

    // Launch with vectorized access - process 4 elements per thread
    const int elements_per_thread = VEC_SIZE;
    const int total_threads = (size + elements_per_thread - 1) / elements_per_thread;
    const int block_size = BLOCK_SIZE;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    dim3 grid(num_blocks);
    dim3 block(block_size);

    hipLaunchKernelGGL(gelu_kernel, grid, block, 0, 0, 
                       x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

