matmul_source = """
#include <hip/hip_runtime.h>

#define BLOCK_M 64
#define BLOCK_N 64
#define BLOCK_K 8

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread indices within block
    int tx = threadIdx.x;  // 0 to 255
    int ty = tx / 16;      // 0 to 15
    int tz = tx % 16;      // 0 to 15

    // Calculate global row and column
    int global_row = by * BLOCK_M + ty * 4;
    int global_col = bx * BLOCK_N + tz * 4;

    // Load tiles into shared memory with vectorization
    __shared__ float As[BLOCK_M][BLOCK_K];
    __shared__ float Bs[BLOCK_K][BLOCK_N];

    int num_tiles_k = (K + BLOCK_K - 1) / BLOCK_K;

    // Accumulators for 4x4 output
    float c00 = 0.0f, c01 = 0.0f, c02 = 0.0f, c03 = 0.0f;
    float c10 = 0.0f, c11 = 0.0f, c12 = 0.0f, c13 = 0.0f;
    float c20 = 0.0f, c21 = 0.0f, c22 = 0.0f, c23 = 0.0f;
    float c30 = 0.0f, c31 = 0.0f, c32 = 0.0f, c33 = 0.0f;

    for (int tile = 0; tile < num_tiles_k; ++tile) {
        // Load A tile (each thread loads 4 elements)
        #pragma unroll
        for (int i = 0; i < 4; ++i) {
            int row = global_row + i;
            int col = tile * BLOCK_K + tz;
            As[ty * 4 + i][tz] = (row < M && col < K) ? A[row * K + col] : 0.0f;
        }

        // Load B tile (each thread loads 4 elements, transposed)
        #pragma unroll
        for (int i = 0; i < 4; ++i) {
            int row = tile * BLOCK_K + ty;
            int col = global_col + i;
            Bs[ty][tz * 4 + i] = (row < K && col < N) ? B[row * N + col] : 0.0f;
        }

        __syncthreads();

        // Compute matrix multiply - each thread computes 4x4 output
        #pragma unroll
        for (int k = 0; k < BLOCK_K; ++k) {
            float a0 = As[ty * 4 + 0][k];
            float a1 = As[ty * 4 + 1][k];
            float a2 = As[ty * 4 + 2][k];
            float a3 = As[ty * 4 + 3][k];

            float b0 = Bs[k][tz * 4 + 0];
            float b1 = Bs[k][tz * 4 + 1];
            float b2 = Bs[k][tz * 4 + 2];
            float b3 = Bs[k][tz * 4 + 3];

            // Matrix multiplication
            c00 += a0 * b0; c01 += a0 * b1; c02 += a0 * b2; c03 += a0 * b3;
            c10 += a1 * b0; c11 += a1 * b1; c12 += a1 * b2; c13 += a1 * b3;
            c20 += a2 * b0; c21 += a2 * b1; c22 += a2 * b2; c23 += a2 * b3;
            c30 += a3 * b0; c31 += a3 * b1; c32 += a3 * b2; c33 += a3 * b3;
        }

        __syncthreads();
    }

    // Write results to C
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            int row = global_row + i;
            int col = global_col + j;
            if (row < M && col < N) {
                C[row * N + col] = (&c00)[i * 4 + j];
            }
        }
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    auto M = A.size(0);
    auto K = A.size(1);
    auto N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 block(256);
    dim3 grid((N + BLOCK_N - 1) / BLOCK_N, (M + BLOCK_M - 1) / BLOCK_M);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        M, K, N
    );

    return C;
}
"""

matmul_lib = load_inline(
    name="matmul_lib",
    cpp_sources=matmul_source,
    functions=["matmul_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) with irregular shapes
    using a tiled HIP kernel with shared memory and 4x4 thread compute.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_hip = matmul_lib

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix multiplication of A and B using optimized HIP kernel.

        Args:
            A: Input tensor with shape (M, K).
            B: Input tensor with shape (K, N).

        Returns:
            C: Output tensor with shape (M, N).
        """
