sum_reduction_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void sum_reduction_kernel(const float* input, float* output, int batch_size, int dim1, int dim2) {
    // Each thread block handles one output element (at position [b, 0, c])
    int output_idx = blockIdx.x;

    // Calculate the output position (b, c)
    int b = output_idx / dim2;
    int c = output_idx % dim2;

    // Shared memory for parallel reduction
    extern __shared__ float shared_data[];

    // Each thread processes multiple elements to improve utilization
    int thread_idx = threadIdx.x;
    int block_size = blockDim.x;

    // Calculate how many elements each thread needs to process
    int total_elements = dim1;
    int elements_per_thread = (total_elements + block_size - 1) / block_size;

    // Compute partial sum for this thread's assigned elements
    float partial_sum = 0.0f;

    for (int i = 0; i < elements_per_thread; i++) {
        int d = thread_idx + i * block_size;
        if (d < total_elements) {
            // Linear index: (b * dim1 + d) * dim2 + c
            int linear_idx = (b * dim1 + d) * dim2 + c;
            partial_sum += input[linear_idx];
        }
    }

    // Store partial sum in shared memory
    shared_data[thread_idx] = partial_sum;
    __syncthreads();

    // Parallel reduction using warp shuffle - need 64-bit mask for AMD/ROCm
    // First, reduce within warps
    #pragma unroll
    for (int offset = 32; offset > 0; offset /= 2) {
        partial_sum = __shfl_down_sync(0xFFFFFFFFFFFFFFFF, partial_sum, offset);
    }

    // Write warp result to shared memory
    int warp_id = thread_idx / 32;
    if (thread_idx % 32 == 0) {
        shared_data[warp_id] = partial_sum;
    }
    __syncthreads();

    // Final reduction of warp results (max 8 warps per block of 256 threads)
    if (thread_idx < 8 && thread_idx < block_size / 32) {
        #pragma unroll
        for (int offset = 8; offset > 0; offset /= 2) {
            shared_data[thread_idx] += __shfl_down_sync(0xFFFFFFFFFFFFFFFF, shared_data[thread_idx], offset);
        }
    }
    __syncthreads();

    // Write final result (first thread writes the output)
    if (thread_idx == 0) {
        int output_linear_idx = b * dim2 + c;
        output[output_linear_idx] = shared_data[0];
    }
}

torch::Tensor sum_reduction_hip(torch::Tensor x, int dim) {
    // Get input dimensions
    int batch_size = x.size(0);
    int dim1 = x.size(1);
    int dim2 = x.size(2);

    // Output shape is (batch_size, 1, dim2) -> flatten to (batch_size, dim2)
    auto output = torch::zeros({batch_size, dim2}, x.options());

    // Number of output elements
    int num_outputs = batch_size * dim2;

    // Launch kernel - one block per output element, 256 threads per block
    dim3 grid(num_outputs);
    dim3 block(256);
    int shared_mem_size = 256 * sizeof(float);

    sum_reduction_kernel<<<grid, block, shared_mem_size>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, dim1, dim2
    );

    // Reshape to (batch_size, 1, dim2)
    return output.view({batch_size, 1, dim2});
}
"""

sum_reduction = load_inline(
    name="sum_reduction",
    cpp_sources=sum_reduction_cpp_source,
    functions=["sum_reduction_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
