rms_norm_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void rms_norm_kernel(const float* __restrict__ x, 
                                float* __restrict__ out, 
                                int batch_size,
                                int features,
                                int dim1,
                                int dim2,
                                float eps) {
    // Each block handles one spatial position (batch_idx, d1_idx, d2_idx)
    int batch_idx = blockIdx.z;
    int d1_idx = blockIdx.y;
    int d2_idx = blockIdx.x;

    // Each thread processes some elements from the features dimension
    int features_per_thread = (features + blockDim.x - 1) / blockDim.x;
    int start_feature = threadIdx.x * features_per_thread;
    int end_feature = min(start_feature + features_per_thread, features);

    // Base pointer for this spatial position
    // Layout: (batch, features, dim1, dim2)
    // stride: batch_size * features * dim1 * dim2 for dim0
    //         features * dim1 * dim2 for dim1
    //         dim1 * dim2 for dim2
    const float* x_ptr = x + ((batch_idx * features + 0) * dim1 + d1_idx) * dim2 + d2_idx;

    // Compute sum of squares for this spatial position
    float sum_sq = 0.0f;
    if (start_feature < features) {
        for (int f = start_feature; f < end_feature; f++) {
            float val = x_ptr[f * dim1 * dim2];
            sum_sq += val * val;
        }
    }

    // Parallel reduction using shared memory
    __shared__ float shared_sums[512];
    shared_sums[threadIdx.x] = sum_sq;
    __syncthreads();

    // Reduce sum_sq across threads
    for (int stride = blockDim.x / 2; stride > 0; stride /= 2) {
        if (threadIdx.x < stride) {
            shared_sums[threadIdx.x] += shared_sums[threadIdx.x + stride];
        }
        __syncthreads();
    }

    // Thread 0 computes RMS and writes to shared memory for all threads
    float rms_val;
    if (threadIdx.x == 0) {
        float mean_sq = shared_sums[0] / features;
        rms_val = sqrtf(mean_sq + eps);
    }
    __syncthreads();

    // Broadcast rms_val to all threads (all threads can read from shared)
    rms_val = shared_sums[0];

    // Write output
    float* out_ptr = out + ((batch_idx * features + 0) * dim1 + d1_idx) * dim2 + d2_idx;
    if (start_feature < features) {
        for (int f = start_feature; f < end_feature; f++) {
            out_ptr[f * dim1 * dim2] = x_ptr[f * dim1 * dim2] / rms_val;
        }
    }
}

torch::Tensor rms_norm_hip(torch::Tensor x, float eps) {
    auto batch_size = x.size(0);
    auto features = x.size(1);
    auto dim1 = x.size(2);
    auto dim2 = x.size(3);

    auto out = torch::zeros_like(x);

    // Use 256 threads per block for good occupancy
    const int block_size = 256;

    // Grid: each block handles one spatial position
    dim3 grid(dim2, dim1, batch_size);

    rms_norm_kernel<<<grid, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        features,
        dim1,
        dim2,
        eps
    );

    return out;
}
"""

