    // 1D block approach for small N dimension
    int row_idx = blockIdx.x * blockDim.y + threadIdx.y;
    int col_idx = blockIdx.y * blockDim.x + threadIdx.x;

    if (row_idx >= M || col_idx >= N) {
        return;
