    // Compute dot product
    float sum = 0.0f;
    #pragma unroll
    for (int k = 0; k < K; k++) {
        sum += A[row_idx * K + k] * B[k * N + col_idx];
    }

    C[row_idx * N + col_idx] = sum;
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    // Get dimensions
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    // Create output tensor
    auto C = torch::zeros({M, N}, A.options());

    // Use 256 threads per block, arranged as 16x16 for better occupancy
    dim3 block(16, 16);
    dim3 grid((N + 15) / 16, (M + 15) / 16);

    // Launch kernel
    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );

    hipError_t err = hipGetLastError();
    if (err != hipSuccess) {
        printf("HIP Error: %s\\n", hipGetErrorString(err));
    }

    return C;
}
