gelu_cpp_source = """
#include <hip/hip_runtime.h>

#define BLOCK_SIZE 1024

// Fast GELU approximation from https://arxiv.org/abs/1606.08415
// GELU(x) ≈ 0.5 * x * (1 + tanh(sqrt(2/π) * (x + 0.044715 * x^3)))
// Optimized by computing tanh using exponential approximation for speed
__global__ void gelu_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    const float sqrt_2_over_pi = 0.7978845608028654f;
    const float cof = 0.044715f;

    // Process in a simple loop with better instruction-level parallelism
    for (; idx < size; idx += blockDim.x * gridDim.x) {
        float x_val = x[idx];
        float x_cube = x_val * x_val * x_val;
        float inner = sqrt_2_over_pi * (x_val + cof * x_cube);

        // Fast tanh approximation using sigmoid
        // tanh(z) ≈ 2*sigmoid(2*z) - 1
        // Use fast approximation for sigmoid: 1/(1+exp(-x))
        float exp_neg_2x = expf(-2.0f * inner);
        float sigmoid_2x = 1.0f / (1.0f + exp_neg_2x);
        float tanh_val = 2.0f * sigmoid_2x - 1.0f;

        out[idx] = 0.5f * x_val * (1.0f + tanh_val);
    }
}

torch::Tensor gelu_hip(torch::Tensor x) {
    int size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = BLOCK_SIZE;
    const int num_blocks = 640; // Use enough blocks to fully utilize the GPU

    dim3 grid(num_blocks);
    dim3 block(block_size);

    hipLaunchKernelGGL(gelu_kernel, grid, block, 0, 0, 
                       x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

