batched_gemm_cpp_source = """
#include <hip/hip_runtime.h>

#define TILE_SIZE_M 64
#define TILE_SIZE_N 64
#define TILE_SIZE_K 16
#define BLOCK_ROWS 8
#define BLOCK_COLS 8

__global__ void batched_gemm_kernel(
    const float* A, const float* B, float* C,
    int batch, int m, int k, int n)
{
    // Batch index
    int batch_idx = blockIdx.z;

    // Batch pointers
    const float* A_batch = A + batch_idx * m * k;
    const float* B_batch = B + batch_idx * k * n;
    float* C_batch = C + batch_idx * m * n;

    // Compute starting row and column for this block
    int row_start = blockIdx.y * TILE_SIZE_M;
    int col_start = blockIdx.x * TILE_SIZE_N;

    // Shared memory for tiles
    __shared__ float A_tile[TILE_SIZE_M][TILE_SIZE_K];
    __shared__ float B_tile[TILE_SIZE_K][TILE_SIZE_N];

    // Accumulator
    float sum[BLOCK_ROWS][BLOCK_COLS];
    #pragma unroll
    for (int i = 0; i < BLOCK_ROWS; i++) {
        #pragma unroll
        for (int j = 0; j < BLOCK_COLS; j++) {
            sum[i][j] = 0.0f;
        }
    }

    // Loop over K dimension in tiles
    for (int t = 0; t < (k + TILE_SIZE_K - 1) / TILE_SIZE_K; ++t) {
        int k_start = t * TILE_SIZE_K;

        // Load A tile (M x K)
        #pragma unroll
        for (int i = 0; i < BLOCK_ROWS; i++) {
            int row = row_start + threadIdx.y * BLOCK_ROWS + i;
            #pragma unroll
            for (int kk = 0; kk < TILE_SIZE_K; kk += 8) {
                int k_idx = k_start + kk + (threadIdx.x % 8);
                float val = 0.0f;
                if (row < m && k_idx < k) {
                    val = A_batch[row * k + k_idx];
                }
                A_tile[threadIdx.y * BLOCK_ROWS + i][k_idx - k_start] = val;
            }
        }

        // Load B tile (K x N)
        #pragma unroll
        for (int j = 0; j < BLOCK_COLS; j++) {
            int col = col_start + threadIdx.x + j * 8;
            #pragma unroll
            for (int kk = 0; kk < TILE_SIZE_K; kk++) {
                int k_idx = k_start + kk;
                float val = 0.0f;
                if (k_idx < k && col < n) {
                    val = B_batch[k_idx * n + col];
                }
                B_tile[k_idx - k_start][col - col_start] = val;
            }
        }

        __syncthreads();

        // Compute partial sums
        #pragma unroll
        for (int i = 0; i < BLOCK_ROWS; i++) {
            #pragma unroll
            for (int j = 0; j < BLOCK_COLS; j++) {
                int a_row = threadIdx.y * BLOCK_ROWS + i;
                int b_col = threadIdx.x + j * 8;
                #pragma unroll
                for (int kk = 0; kk < TILE_SIZE_K; kk++) {
                    sum[i][j] += A_tile[a_row][kk] * B_tile[kk][b_col];
                }
            }
        }

        __syncthreads();
    }

    // Write results
    #pragma unroll
    for (int i = 0; i < BLOCK_ROWS; i++) {
        int row = row_start + threadIdx.y * BLOCK_ROWS + i;
        if (row < m) {
            #pragma unroll
            for (int j = 0; j < BLOCK_COLS; j++) {
                int col = col_start + threadIdx.x + j * 8;
                if (col < n) {
                    C_batch[row * n + col] = sum[i][j];
                }
            }
        }
    }
}

torch::Tensor batched_gemm_hip(torch::Tensor A, torch::Tensor B) {
    // Get dimensions
    int batch = A.size(0);
    int m = A.size(1);
    int k = A.size(2);
    int n = B.size(2);

    // Create output tensor with correct shape (batch, m, n)
    auto C = torch::zeros({batch, m, n}, A.options());

    // Launch kernel
    dim3 block(TILE_SIZE_N / BLOCK_COLS, TILE_SIZE_M / BLOCK_ROWS);
    dim3 grid(
        (n + TILE_SIZE_N - 1) / TILE_SIZE_N,
        (m + TILE_SIZE_M - 1) / TILE_SIZE_M,
        batch
    );

    batched_gemm_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        batch, m, k, n
    );

    return C;
}
"""

batched_gemm = load_inline(
    name="batched_gemm",
    cpp_sources=batched_gemm_cpp_source,
    functions=["batched_gemm_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Performs batched matrix multiplication (C = A * B) where A, B, and C have the same batch dimension.
    Uses an optimized HIP kernel with tiling for better memory access patterns.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.batched_gemm = batched_gemm

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs batched matrix multiplication using optimized HIP kernel.

        Args:
            A: Input tensor of shape (batch_size, m, k).
            B: Input tensor of shape (batch_size, k, n).

        Returns:
            C: Output tensor of shape (batch_size, m, n).
        """
        # Ensure tensors are on GPU and contiguous
        A = A.cuda().contiguous()
        B = B.cuda().contiguous()

        return self.batched_gemm.batched_gemm_hip(A, B)

