maxpool2d_cpp_source = """
#include <hip/hip_runtime.h>

#define TILE_SIZE 16
#define MAX_POOL_RADIUS 2

// Helper to unroll the 4x4 pooling window
__device__ __forceinline__ float compute_max_pool_4x4(
    const float* shared_mem,
    const int ty,
    const int tx,
    const int halo_top,
    const int halo_bottom,
    const int halo_left,
    const int halo_right,
    const int tile_pitch
) {
    float max_val = -1e20f;

    // Unrolled 4x4 max pool loop for kernel_size=4
    #pragma unroll 4
    for (int ky = 0; ky < 4; ++ky) {
        int y = ty + ky - MAX_POOL_RADIUS;
        bool valid_y = (halo_top <= y && y < TILE_SIZE + halo_bottom);

        #pragma unroll 4
        for (int kx = 0; kx < 4; ++kx) {
            if (valid_y) {
                int x = tx + kx - MAX_POOL_RADIUS;
                bool valid_x = (halo_left <= x && x < TILE_SIZE + halo_right);

                if (valid_x) {
                    float val = shared_mem[y * tile_pitch + x];
                    max_val = fmaxf(max_val, val);
                }
            }
        }
    }

    return max_val;
}

__global__ void maxpool2d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int batch_size,
    const int channels,
    const int height,
    const int width,
    const int out_height,
    const int out_width,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation
) {
    const int out_x = blockIdx.x * TILE_SIZE + threadIdx.x;
    const int out_y = blockIdx.y * TILE_SIZE + threadIdx.y;
    const int channel = blockIdx.z;
    const int batch = blockIdx.z / channels;

    const int actual_channel = blockIdx.z % channels;

    __shared__ float tile[(TILE_SIZE + 2 * MAX_POOL_RADIUS) * (TILE_SIZE + 2 * MAX_POOL_RADIUS)];

    const int effective_tile_size = TILE_SIZE + 2 * MAX_POOL_RADIUS;

    // Load data into shared memory with halo
    const int global_y = out_y * stride - padding;  
    const int global_x = out_x * stride - padding;

    // Each thread loads one element
    const int load_y = threadIdx.y + MAX_POOL_RADIUS;
    const int load_x = threadIdx.x + MAX_POOL_RADIUS;
    const int load_idx = load_y * effective_tile_size + load_x;

    const int input_y = global_y + threadIdx.y * stride;
    const int input_x = global_x + threadIdx.x * stride;

    if (input_y >= 0 && input_y < height && input_x >= 0 && input_x < width) {
        const int input_idx = ((batch * channels + actual_channel) * height + input_y) * width + input_x;
        tile[load_idx] = input[input_idx];
    } else {
        tile[load_idx] = -1e20f;
    }

    // Boundary handling - load halo regions
    // Top halo
    if (threadIdx.y < MAX_POOL_RADIUS) {
        const int halo_y = threadIdx.y;
        const int halo_global_y = out_y * stride - padding + (halo_y - MAX_POOL_RADIUS);

        const int halo_idx = halo_y * effective_tile_size + load_x;
        if (halo_global_y >= 0 && halo_global_y < height && input_x >= 0 && input_x < width) {
            const int input_idx = ((batch * channels + actual_channel) * height + halo_global_y) * width + input_x;
            tile[halo_idx] = input[input_idx];
        } else {
            tile[halo_idx] = -1e20f;
        }
    }

    // Bottom halo
    const int last_row_y = TILE_SIZE + MAX_POOL_RADIUS;
    if (threadIdx.y == TILE_SIZE - 1) {
        for (int hy = 1; hy <= MAX_POOL_RADIUS; ++hy) {
            const int halo_y = last_row_y + hy;
            const int halo_global_y = (out_y * stride - padding) + (threadIdx.y + hy) * stride;

            const int halo_idx = halo_y * effective_tile_size + load_x;
            if (halo_global_y >= 0 && halo_global_y < height && input_x >= 0 && input_x < width) {
                const int input_idx = ((batch * channels + actual_channel) * height + halo_global_y) * width + input_x;
                tile[halo_idx] = input[input_idx];
            } else {
                tile[halo_idx] = -1e20f;
            }
        }
    }

    __syncthreads();

    // Compute max pool using shared memory
    if (out_x < out_width && out_y < out_height) {
        const int halo_top = MAX_POOL_RADIUS;
        const int halo_bottom = MAX_POOL_RADIUS;
        const int halo_left = MAX_POOL_RADIUS;
        const int halo_right = MAX_POOL_RADIUS;

        const float max_val = compute_max_pool_4x4(
            tile,
            threadIdx.y + MAX_POOL_RADIUS,
            threadIdx.x + MAX_POOL_RADIUS,
            halo_top,
            halo_bottom,
            halo_left,
            halo_right,
            effective_tile_size
        );

        const int output_idx = ((batch * channels + actual_channel) * out_height + out_y) * out_width + out_x;
        output[output_idx] = max_val;
    }
}

torch::Tensor maxpool2d_hip(
    torch::Tensor input,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation
) {
    const int batch_size = input.size(0);
    const int channels = input.size(1);
    const int height = input.size(2);
    const int width = input.size(3);

    const int out_height = (height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    const int out_width = (width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, channels, out_height, out_width}, input.options());

    const dim3 block_size(16, 16);
    const dim3 grid_size(
        (out_width + 15) / 16,
        (out_height + 15) / 16,
        batch_size * channels
    );

    maxpool2d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width,
        out_height,
        out_width,
        kernel_size,
        stride,
        padding,
        dilation
    );

    return output;
}
"""

