    const int block_size = 256;
    const int grid_size = (M + block_size - 1) / block_size;

    matvec_kernel<<<grid_size, block_size>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
