batched_gemm_cpp_source = """
#include <hip/hip_runtime.h>

#define BLOCK_M 64
#define BLOCK_N 64
#define BLOCK_K 16

__global__ void batched_gemm_kernel(
    const float* A, const float* B, float* C,
    int batch, int m, int k, int n)
{
    int batch_idx = blockIdx.z;

    // Get pointers to this batch
    const float* A_batch = A + batch_idx * m * k;
    const float* B_batch = B + batch_idx * k * n;
    float* C_batch = C + batch_idx * m * n;

    // Thread and block indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Starting position in C
    int row_start = by * BLOCK_M;
    int col_start = bx * BLOCK_N;

    // Shared memory for blocking
    __shared__ float As[BLOCK_M][BLOCK_K];
    __shared__ float Bs[BLOCK_K][BLOCK_N];

    // Accumulators
    float c[BLOCK_M/8][BLOCK_N/8];
    #pragma unroll
    for (int i = 0; i < BLOCK_M/8; i++) {
        #pragma unroll
        for (int j = 0; j < BLOCK_N/8; j++) {
            c[i][j] = 0.0f;
        }
    }

    // Loop over K dimension
    for (int kk = 0; kk < (k + BLOCK_K - 1) / BLOCK_K; kk++) {
        int k_start = kk * BLOCK_K;

        // Load A tile
        for (int i = 0; i < BLOCK_M; i += 8) {
            int row = row_start + ty * 8 + i;
            for (int j = 0; j < BLOCK_K; j++) {
                int col = k_start + tx + j * 8;
                float val = 0.0f;
                if (row < m && col < k) {
                    val = A_batch[row * k + col];
                }
                As[ty * 8 + i][j] = val;
            }
        }

        // Load B tile
        for (int i = 0; i < BLOCK_K; i++) {
            int row = k_start + tx + i * 8;
            for (int j = 0; j < BLOCK_N; j += 8) {
                int col = col_start + ty * 8 + j;
                float val = 0.0f;
                if (row < k && col < n) {
                    val = B_batch[row * n + col];
                }
                Bs[i][ty * 8 + j] = val;
            }
        }

        __syncthreads();

        // Compute
        for (int l = 0; l < BLOCK_K; l++) {
            #pragma unroll
            for (int i = 0; i < BLOCK_M/8; i++) {
                #pragma unroll
                for (int j = 0; j < BLOCK_N/8; j++) {
                    c[i][j] += As[ty * 8 + i * 8][l] * Bs[l][tx + j * 8];
                }
            }
        }

        __syncthreads();
    }

    // Store C tile
    for (int i = 0; i < BLOCK_M/8; i++) {
        int row = row_start + ty * 8 + i * 8;
        if (row < m) {
            for (int j = 0; j < BLOCK_N/8; j++) {
                int col = col_start + tx + j * 8;
                if (col < n) {
                    C_batch[row * n + col] = c[i][j];
                }
            }
        }
    }
}

torch::Tensor batched_gemm_hip(torch::Tensor A, torch::Tensor B) {
    int batch = A.size(0);
    int m = A.size(1);
    int k = A.size(2);
