    dim3 block(8, 8);
    dim3 grid(
        (n + BLOCK_N - 1) / BLOCK_N,
        (m + BLOCK_M - 1) / BLOCK_M,
        batch
    );

    batched_gemm_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        batch, m, k, n
    );

    return C;
}
