#include <hip/hip_runtime.h>

__global__ void rms_norm_kernel(const float* __restrict__ x, 
                                float* __restrict__ out, 
                                int batch_size,
                                int features,
                                int dim1,
                                int dim2,
                                float eps) {
    // Each block handles one spatial position (batch_idx, d1_idx, d2_idx)
    int batch_idx = blockIdx.z;
    int d1_idx = blockIdx.y;
    int d2_idx = blockIdx.x;

    // Each thread processes some elements from the features dimension
    int features_per_thread = (features + blockDim.x - 1) / blockDim.x;
    int start_feature = threadIdx.x * features_per_thread;
    int end_feature = min(start_feature + features_per_thread, features);

    // Compute sum of squares for this spatial position across features
    // Tensor layout: (batch, features, dim1, dim2)
    // Contiguous: last dimension changes fastest
    float sum_sq = 0.0f;

    const int spatial_stride = dim1 * dim2;
    const int batch_stride = features * spatial_stride;

    int base_offset = batch_idx * batch_stride + d1_idx * dim2 + d2_idx;

    if (start_feature < features) {
        for (int f = start_feature; f < end_feature; f++) {
            int idx = base_offset + f * spatial_stride;
            float val = x[idx];
            sum_sq += val * val;
        }
    }

    // Reduce sum_ssq across threads using shared memory
    __shared__ float shared_sum[512];
    shared_sum[threadIdx.x] = sum_sq;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride /= 2) {
        if (threadIdx.x < stride) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + stride];
        }
        __syncthreads();
    }

    // Thread 0 computes RMS and stores in shared_sum[0]
    if (threadIdx.x == 0) {
        float mean_sq = shared_sum[0] / (float)features;
        shared_sum[0] = sqrtf(mean_sq + eps);
    }
    __syncthreads();

    float rms_val = shared_sum[0];

    // Write normalized output
    if (start_feature < features) {
        for (int f = start_feature; f < end_feature; f++) {
            int idx = base_offset + f * spatial_stride;
            out[idx] = x[idx] / rms_val;
        }
    }
}

