# Generate unique extension name to avoid cache conflicts
ext_name = f"matmul_{int(time.time()) % 10000}"

matmul_hip_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define BLOCK_SIZE 64
#define BLOCK_SIZE_K 16

__global__ void matmul_kernel(
    const float* A,
    const float* B,
    float* C,
    int M, int K, int N
) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each thread computes 4x4 tile
    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    // Register tiling for C values
    float C00 = 0.0f, C01 = 0.0f, C02 = 0.0f, C03 = 0.0f;
    float C10 = 0.0f, C11 = 0.0f, C12 = 0.0f, C13 = 0.0f;
    float C20 = 0.0f, C21 = 0.0f, C22 = 0.0f, C23 = 0.0f;
    float C30 = 0.0f, C31 = 0.0f, C32 = 0.0f, C33 = 0.0f;

    // Shared memory for A and B tiles
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE_K];
    __shared__ float Bs[BLOCK_SIZE_K][BLOCK_SIZE];

    int num_tiles = (K + BLOCK_SIZE_K - 1) / BLOCK_SIZE_K;

    for (int t = 0; t < num_tiles; ++t) {
        // Load A tile (each thread loads 4 elements)
        int k_start = t * BLOCK_SIZE_K;

        #pragma unroll
        for (int i = 0; i < 4; ++i) {
            int a_row = row + i * 16;
            if (a_row < M) {
                #pragma unroll
                for (int j = 0; j < 4; ++j) {
                    int a_col = k_start + tx * 4 + j;
                    if (a_col < K) {
                        As[a_row % BLOCK_SIZE][a_col % BLOCK_SIZE_K] = A[a_row * K + a_col];
                    } else {
                        As[a_row % BLOCK_SIZE][a_col % BLOCK_SIZE_K] = 0.0f;
                    }
                }
            }
        }

        // Load B tile (each thread loads 4 elements)
        #pragma unroll
        for (int i = 0; i < 4; ++i) {
            int b_col = col + i * 16;
            if (b_col < N) {
                #pragma unroll
                for (int j = 0; j < 4; ++j) {
                    int b_row = k_start + ty * 4 + j;
                    if (b_row < K) {
                        Bs[b_row % BLOCK_SIZE_K][b_col % BLOCK_SIZE] = B[b_row * N + b_col];
                    } else {
                        Bs[b_row % BLOCK_SIZE_K][b_col % BLOCK_SIZE] = 0.0f;
                    }
                }
            }
        }

        __syncthreads();

        // Compute 4x4 tile
        #pragma unroll
        for (int k = 0; k < BLOCK_SIZE_K; ++k) {
            float A0 = As[ty][k];
            float A1 = As[ty + 16][k];
            float A2 = As[ty + 32][k];
            float A3 = As[ty + 48][k];

            float B0 = Bs[k][tx];
            float B1 = Bs[k][tx + 16];
            float B2 = Bs[k][tx + 32];
            float B3 = Bs[k][tx + 48];

            C00 += A0 * B0; C01 += A0 * B1; C02 += A0 * B2; C03 += A0 * B3;
            C10 += A1 * B0; C11 += A1 * B1; C12 += A1 * B2; C13 += A1 * B3;
            C20 += A2 * B0; C21 += A2 * B1; C22 += A2 * B2; C23 += A2 * B3;
            C30 += A3 * B0; C31 += A3 * B1; C32 += A3 * B2; C33 += A3 * B3;
        }

        __syncthreads();
    }

    // Store results to global memory - properly index each register
    for (int i = 0; i < 4; ++i) {
        int out_row = row + i * 16;
        if (out_row < M) {
            for (int j = 0; j < 4; ++j) {
                int out_col = col + j * 16;
                if (out_col < N) {
                    if (i == 0) {
                        if (j == 0) C[out_row * N + out_col] = C00;
                        else if (j == 1) C[out_row * N + out_col] = C01;
                        else if (j == 2) C[out_row * N + out_col] = C02;
                        else C[out_row * N + out_col] = C03;
                    } else if (i == 1) {
                        if (j == 0) C[out_row * N + out_col] = C10;
                        else if (j == 1) C[out_row * N + out_col] = C11;
                        else if (j == 2) C[out_row * N + out_col] = C12;
                        else C[out_row * N + out_col] = C13;
                    } else if (i == 2) {
                        if (j == 0) C[out_row * N + out_col] = C20;
                        else if (j == 1) C[out_row * N + out_col] = C21;
                        else if (j == 2) C[out_row * N + out_col] = C22;
                        else C[out_row * N + out_col] = C23;
                    } else {
                        if (j == 0) C[out_row * N + out_col] = C30;
                        else if (j == 1) C[out_row * N + out_col] = C31;
                        else if (j == 2) C[out_row * N + out_col] = C32;
                        else C[out_row * N + out_col] = C33;
                    }
                }
            }
        }
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 blockDim(16, 16);  // 256 threads per block
    dim3 gridDim((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (M + BLOCK_SIZE - 1) / BLOCK_SIZE);

    matmul_kernel<<<gridDim, blockDim>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, K, N);

    return C;
}
