matmul_cpp_source = """
#include <hip/hip_runtime.h>

#define MC 128  // Rows per thread block
#define NC 64   // Cols per thread block
#define KC 8    // Tile dimension in K
#define MR 4    // Rows per thread
#define NR 4    // Cols per thread

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[MC][KC];
    __shared__ float Bs[KC][NC];

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = blockIdx.y * MC + ty;
    int col = blockIdx.x * NC + tx;

    // Accumulation registers
    float acc[MR][NR] = {{0.0f}};

    int nTiles = (N + KC - 1) / KC;

    for (int t = 0; t < nTiles; ++t) {
        // Load A tile (coalesced)
        #pragma unroll
        for (int m = 0; m < MR; ++m) {
            int loadRow = row + m * (MC / MR);
            int loadCol = t * KC + tx;
            if (loadRow < N && loadCol < N) {
                As[ty * (MC / MR) + m][tx] = A[loadRow * N + loadCol];
            } else {
                As[ty * (MC / MR) + m][tx] = 0.0f;
            }
        }

        // Load B tile (coalesced)
        #pragma unroll
        for (int n = 0; n < NR; ++n) {
            int loadRow = t * KC + ty;
            int loadCol = col + n * (NC / NR);
            if (loadRow < N && loadCol < N) {
                Bs[ty][tx * (NC / NR) + n] = B[loadRow * N + loadCol];
            } else {
                Bs[ty][tx * (NC / NR) + n] = 0.0f;
            }
        }

        __syncthreads();

        // Accumulate
        #pragma unroll
        for (int k = 0; k < KC; ++k) {
            #pragma unroll
            for (int m = 0; m < MR; ++m) {
                #pragma unroll
                for (int n = 0; n < NR; ++n) {
                    acc[m][n] += As[ty * (MC / MR) + m][k] * Bs[k][tx * (NC / NR) + n];
                }
            }
        }

        __syncthreads();
    }

    // Store result
    #pragma unroll
    for (int m = 0; m < MR; ++m) {
        int storeRow = row + m * (MC / MR);
        #pragma unroll
        for (int n = 0; n < NR; ++n) {
            int storeCol = col + n * (NC / NR);
            if (storeRow < N && storeCol < N) {
                C[storeRow * N + storeCol] = acc[m][n];
            }
        }
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block(NC / NR, MC / MR);
    dim3 grid((N + NC - 1) / NC, (N + MC - 1) / MC);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
"""

