layernorm_cpp_source = """
#include <hip/hip_runtime.h>

#define EPSILON 1e-5f

__global__ void layernorm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int batch_size,
    int features,
    int normalized_size)
{
    int batch_idx = blockIdx.y;
    int feat_idx = blockIdx.x;

    if (batch_idx >= batch_size || feat_idx >= features) return;

    int base_offset = (batch_idx * features + feat_idx) * normalized_size;
    int elements_per_thread = (normalized_size + blockDim.x - 1) / blockDim.x;
    int start = threadIdx.x * elements_per_thread;
    int end = min(start + elements_per_thread, normalized_size);

    // Compute sum
    float sum = 0.0f;
    #pragma unroll
    for (int i = start; i < end; i++) {
        sum += input[base_offset + i];
    }

    // Reduce within warp
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        sum += __shfl_down(sum, offset);
    }
    __syncthreads();

    // Reduce warps
    __shared__ float sdata[32];
    int lane = threadIdx.x % 32;
    int warp = threadIdx.x / 32;
    if (lane == 0) sdata[warp] = sum;
    __syncthreads();

    sum = (threadIdx.x < 32) ? sdata[threadIdx.x] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        sum += __shfl_down(sum, offset);
    }

    float mean = sum / normalized_size;

    // Broadcast mean
    if (threadIdx.x == 0) sdata[0] = mean;
    __syncthreads();
    mean = sdata[0];

    // Compute variance
    float var_sum = 0.0f;
    #pragma unroll
    for (int i = start; i < end; i++) {
        float diff = input[base_offset + i] - mean;
        var_sum += diff * diff;
    }

    // Reduce var_sum
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        var_sum += __shfl_down(var_sum, offset);
    }
    __syncthreads();

    if (lane == 0) sdata[warp] = var_sum;
    __syncthreads();

    var_sum = (threadIdx.x < 32) ? sdata[threadIdx.x] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        var_sum += __shfl_down(var_sum, offset);
    }

    float variance = var_sum / normalized_size;
    float inv_std = rsqrtf(variance + EPSILON);

    // Broadcast inv_std
    if (threadIdx.x == 0) sdata[0] = inv_std;
    __syncthreads();
    inv_std = sdata[0];

    // Apply normalization
    float g = gamma[feat_idx];
    float b = beta[feat_idx];
    #pragma unroll
    for (int i = start; i < end; i++) {
        output[base_offset + i] = g * (input[base_offset + i] - mean) * inv_std + b;
    }
}

torch::Tensor layernorm_hip(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta) {
    auto output = torch::zeros_like(input);
    int batch_size = input.size(0);
    int features = input.size(1);
    int dim1 = input.size(2);
    int dim2 = input.size(3);
    int normalized_size = dim1 * dim2;

