    int ty = threadIdx.y;

    int row = by * TILE + ty;
    int col = bx * TILE + tx;

    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    float sum = 0.0f;
    int tiles = (K + TILE - 1) / TILE;

    for (int t = 0; t < tiles; ++t) {
        int a_col = t * TILE + tx;
        As[ty][tx] = (row < M && a_col < K) ? A[row * K + a_col] : 0.0f;

        int b_row = t * TILE + ty;
        Bs[ty][tx] = (b_row < K && col < N) ? B[b_row * N + col] : 0.0f;

        __syncthreads();

        int k_max = min((t + 1) * TILE, K);
        int k_start = t * TILE;

        for (int k = k_start; k < k_max; ++k) {
            float a = As[ty][k - k_start];
            float b = Bs[k - k_start][tx];
            sum += a * b;
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    auto M = A.size(0);
    auto K = A.size(1);
    auto N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (M + TILE - 1) / TILE);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        M, K, N
    );

    return C;
}
