#include <hip/hip_runtime.h>

// Straightforward GELU kernel with optimal block size for MI300X
__global__ void gelu_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Process multiple elements per thread for better memory efficiency
    const int stride = blockDim.x * gridDim.x;

    for (; idx < size; idx += stride) {
        float x_val = x[idx];

        // GELU(x) = 0.5 * x * (1 + tanh(sqrt(2/π) * (x + 0.044715 * x^3)))
        const float sqrt_2_over_pi = 0.7978845608028654f;
        const float coef = 0.044715f;

        float x_cubed = x_val * x_val * x_val;
        float tanh_in = sqrt_2_over_pi * (x_val + coef * x_cubed);
        float tanh_val = tanhf(tanh_in);

        out[idx] = 0.5f * x_val * (1.0f + tanh_val);
    }
}

torch::Tensor gelu_hip(torch::Tensor x) {
    int size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;
    // Cap at reasonable number of blocks for MI300X
    num_blocks = min(num_blocks, 65536);

    dim3 grid(num_blocks);
    dim3 block(block_size);

    hipLaunchKernelGGL(gelu_kernel, grid, block, 0, 0, 
                       x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

