layernorm_cpp_source = """
#include <hip/hip_runtime.h>

#define EPSILON 1e-5f

__global__ void layernorm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int batch_size,
    int features,
    int dim1,
    int dim2,
    int normalized_size)
{
    int batch_idx = blockIdx.y;
    int flat_feat_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size || flat_feat_idx >= normalized_size) return;

    int batch_offset = batch_idx * normalized_size;
    int idx = batch_offset + flat_feat_idx;

    // Load element
    float val = input[idx];

    // Compute mean
    __shared__ float shmem[1024];
    shmem[threadIdx.x] = val;
    __syncthreads();

    // Reduce sum
    float sum = 0.0f;
    for (int i = 0; i < blockDim.x; i++) {
        sum += (i + blockIdx.x * blockDim.x < normalized_size) ? shmem[i] : 0.0f;
    }

    // Warp reduction
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        sum += __shfl_down(sum, offset);
    }
    __syncthreads();

    float mean = sum / normalized_size;
    if (threadIdx.x == 0) shmem[0] = mean;
    __syncthreads();
    mean = shmem[0];

    // Update for var: (x - mean)^2
    float diff = val - mean;
    shmem[threadIdx.x] = diff * diff;
    __syncthreads();

    // Reduce var sum
    float var_sum = 0.0f;
    for (int i = 0; i < blockDim.x; i++) {
        var_sum += (i + blockIdx.x * blockDim.x < normalized_size) ? shmem[i] : 0.0f;
    }
    var_sum /= normalized_size;

    // Warp reduce final var_sum
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        var_sum += __shfl_down(var_sum, offset);
    }
    __syncthreads();

    float variance = var_sum;
    float inv_std = rsqrtf(variance + EPSILON);

    // Apply normalization with gamma and beta
    output[idx] = gamma[flat_feat_idx] * diff * inv_std + beta[flat_feat_idx];
}

torch::Tensor layernorm_hip(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta) {
    auto output = torch::zeros_like(input);
    int batch_size = input.size(0);
    int features = input.size(1);
    int dim1 = input.size(2);
    int dim2 = input.size(3);
    int normalized_size = features * dim1 * dim2;

    int block_size = 256;
    int num_blocks = (normalized_size + block_size - 1) / block_size;

    dim3 grid(num_blocks, batch_size);

    layernorm_kernel<<<grid, block_size>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        features,
        dim1,
        dim2,
        normalized_size
    );

    return output;
}
