        __syncthreads();

        if (row < M) {
            const float* A_row = &A[row * K + tile_start];
            int elements = min(TILE_SIZE, K - tile_start);
            for (int j = 0; j < elements; j++) {
                sum += A_row[j] * B_shared[j];
            }
        }
        __syncthreads();
    }

    if (row < M) {
        C[row] = sum;
    }
}

