    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block(32, 8); // 256 threads per block
    int gridX = (N + TILE_SIZE - 1) / TILE_SIZE;
    int gridY = (N + TILE_SIZE - 1) / TILE_SIZE;
    dim3 grid(gridX, gridY);

    matmul_kernel<<<grid, block, 0, 0>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
