# Custom HIP kernel for 2D convolution
conv2d_hip_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int in_height,
    const int in_width,
    const int out_height,
    const int out_width,
    const int kernel_height,
    const int kernel_width,
    const int stride_h,
    const int stride_w,
    const int pad_h,
    const int pad_w,
    const int dilation_h,
    const int dilation_w,
    const int groups) {

    // Output position
    const int out_x = blockIdx.x * blockDim.x + threadIdx.x;
    const int out_y = blockIdx.y * blockDim.y + threadIdx.y;
    const int out_c = blockIdx.z;

    if (out_x >= out_width || out_y >= out_height || out_c >= out_channels) return;

    // Calculate input region
    const int in_y_start = out_y * stride_h - pad_h;
    const int in_x_start = out_x * stride_w - pad_w;

    float sum = 0.0f;

    // Loop over input channels and kernel
    for (int in_c = 0; in_c < in_channels; ++in_c) {
        for (int ky = 0; ky < kernel_height; ++ky) {
            const int in_y = in_y_start + ky * dilation_h;
            if (in_y < 0 || in_y >= in_height) continue;

            for (int kx = 0; kx < kernel_width; ++kx) {
                const int in_x = in_x_start + kx * dilation_w;
                if (in_x < 0 || in_x >= in_width) continue;

                // Compute indices
                const int input_idx = 
                    (in_c * in_height + in_y) * in_width + in_x;
                const int weight_idx = 
                    out_c * in_channels * kernel_height * kernel_width +
                    in_c * kernel_height * kernel_width +
                    ky * kernel_width + kx;

                sum += input[input_idx] * weight[weight_idx];
            }
        }
    }

    // Add bias if available
    if (bias != nullptr) {
        sum += bias[out_c];
    }

    // Write output for all batches
    for (int b = 0; b < batch_size; ++b) {
        const int output_idx = 
            (b * out_channels + out_c) * out_height * out_width +
            out_y * out_width + out_x;
        output[output_idx] = sum;
    }
}

torch::Tensor conv2d_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h,
    int stride_w,
    int padding_h,
    int padding_w,
    int dilation_h,
    int dilation_w,
    int groups) {

    const auto batch_size = input.size(0);
    const auto in_channels = input.size(1);
    const auto in_height = input.size(2);
    const auto in_width = input.size(3);
    const auto out_channels = weight.size(0);
    const auto kernel_height = weight.size(2);
    const auto kernel_width = weight.size(3);

    const auto out_height = (in_height + 2 * padding_h - dilation_h * (kernel_height - 1) - 1) / stride_h + 1;
