__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int in_height,
    const int in_width,
    const int out_height,
    const int out_width,
    const int kernel_height,
    const int kernel_width,
    const int stride_h,
    const int stride_w,
    const int pad_h,
    const int pad_w,
    const int dilation_h,
    const int dilation_w) {

    // Get thread indices for 4D output tensor
    const int out_z = blockIdx.z * blockDim.z + threadIdx.z;  // batch
    const int out_y = blockIdx.y * blockDim.y + threadIdx.y;  // output height
    const int out_x = blockIdx.x * blockDim.x + threadIdx.x;  // output width

    if (out_z >= batch_size || out_y >= out_height || out_x >= out_width) return;

    // Each block processes multiple output channels
    const int in_c_start = blockIdx.y;

    // Get flattened indices for input access
    const int input_base = out_z * in_channels * in_height * in_width;
    const int output_base = out_z * out_channels * out_height * out_width;

    // Loop over all output channels
    for (int out_c = 0; out_c < out_channels; ++out_c) {
        float sum = 0.0f;

        // Calculate input region start positions
        const int in_y_start = out_y * stride_h - pad_h;
        const int in_x_start = out_x * stride_w - pad_w;

        // Convolution: loop over input channels and kernel
        for (int in_c = 0; in_c < in_channels; ++in_c) {
            for (int ky = 0; ky < kernel_height; ++ky) {
                const int in_y = in_y_start + ky * dilation_h;
                if (in_y < 0 || in_y >= in_height) continue;

                for (int kx = 0; kx < kernel_width; ++kx) {
                    const int in_x = in_x_start + kx * dilation_w;
                    if (in_x < 0 || in_x >= in_width) continue;

                    // Compute flattened indices
                    const int input_idx = input_base + 
                        in_c * in_height * in_width + 
                        in_y * in_width + in_x;
                    const int weight_idx = out_c * in_channels * kernel_height * kernel_width +
                        in_c * kernel_height * kernel_width +
                        ky * kernel_width + kx;

                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }

        // Add bias if available
        if (bias != nullptr) {
            sum += bias[out_c];
        }

        // Write output
        const int output_idx = output_base + 
            out_c * out_height * out_width + 
            out_y * out_width + out_x;
        output[output_idx] = sum;
    }
}

